import 'package:binary_codec/binary_codec.dart';

void main() {
  final data = {'name': 'Alice', 'age': 30, 'active': true};
  final bytes = BinaryCodec.encode(data);
  final decoded = BinaryCodec.decode(bytes) as Map;
  print(decoded); // {name: Alice, age: 30, active: true}
}
